const truth = (text, value, why) => ({ text, truth: value, why });

function makeQuestions(caseItem) {
  const common = {
    caseId: caseItem.id,
    reasoningSkills: caseItem.reasoningSkills,
    knowledgeDomains: [caseItem.domain],
    misconceptions: caseItem.misconceptions
  };
  return [
    {
      ...common,
      id: `${caseItem.id}:conclusion`,
      format: "single",
      prompt: "Which conclusion is best supported by the evidence shown so far?",
      options: [caseItem.conclusion, caseItem.overreach, caseItem.alternative, "The measurements cannot distinguish any biological models."],
      answer: caseItem.conclusion,
      explanation: caseItem.conclusionWhy,
      whyOthersFail: `The stronger claim goes beyond the measurements. ${caseItem.alternativeWhy}`,
      skill: "Evidence → conclusion"
    },
    {
      ...common,
      id: `${caseItem.id}:prediction`,
      format: "single",
      prompt: caseItem.predictionPrompt,
      options: [caseItem.prediction, caseItem.reversePrediction, "Every measured feature must return to wild type.", "No measurable feature should change."],
      answer: caseItem.prediction,
      explanation: caseItem.predictionWhy,
      whyOthersFail: "A pathway prediction should follow the stated direction of regulation; it does not imply that every phenotype is fully rescued.",
      skill: "Perturbation prediction"
    },
    {
      ...common,
      id: `${caseItem.id}:experiment`,
      format: "single",
      prompt: "Which next experiment would most directly distinguish the proposed mechanism from the alternative explanation?",
      options: [caseItem.nextExperiment, caseItem.controlOnly, "Increase the sample size for the same single endpoint without adding a new condition.", "Measure an unrelated pathway in a different developmental stage."],
      answer: caseItem.nextExperiment,
      explanation: caseItem.experimentWhy,
      whyOthersFail: "A control can validate the assay, but only the proposed comparison changes the causal variable that separates the two models.",
      skill: "Experimental design"
    },
    {
      ...common,
      id: `${caseItem.id}:truth-grid`,
      format: "truth-grid",
      prompt: "Classify each statement as supported or not supported by this case.",
      statements: caseItem.statements,
      explanation: "Treat each statement separately. Four correct earns full credit; three earns 0.6; two earns 0.2.",
      whyOthersFail: "An association can support a model without proving exclusivity, direct binding, or action in every tissue.",
      skill: "Claims and limitations"
    }
  ];
}

