export const OLYMPIAD_CASES = topics.flatMap(topic => topic.experiments.map((experiment, index) => {
  const caseItem = {
    id: `worm-${topic.id}-${experiment.id}`,
    title: experiment.title,
    organism: "Caenorhabditis elegans",
    context: experiment.intro,
    background: topic.background,
    domain: topic.domain,
    difficulty: topic.difficulty,
    articleDerived: topic.articleDerived && index === 0,
    sourceType: topic.articleDerived && index === 0 ? "article-inspired; displayed values may be schematic" : "curated original teaching case",
    evidenceLevel: topic.articleDerived ? "high" : "moderate",
    reviewStatus: "verified",
    sourceIds: topic.sourceIds,
    genes: topic.genes,
    where: topic.where,
    mechanism: topic.mechanism,
    data: { columns: ["Condition", "Molecular readout", "Phenotype / interpretation"], rows: experiment.rows },
    conclusion: experiment.conclusion,
    conclusionWhy: `${experiment.conclusion} This is the narrowest claim that explains the compared conditions without assuming exclusivity.`,
    overreach: experiment.overreach,
    alternative: experiment.alternative,
    alternativeWhy: experiment.alternativeWhy,
    predictionPrompt: `What should happen if researchers ${experiment.intervention}?`,
    prediction: experiment.prediction,
    reversePrediction: experiment.reversePrediction,
    predictionWhy: `${experiment.prediction} That direction follows the functional order in the pathway model.`,
    nextExperiment: experiment.nextExperiment,
    controlOnly: experiment.controlOnly,
    experimentWhy: `${experiment.nextExperiment} This comparison changes the variable that separates the proposed model from its alternative.`,
    limitation: experiment.limit,
    reasoningSkills: ["mechanism", "perturbation", "experimental design", "claims vs evidence"],
    misconceptions: ["correlation proves direct causation", "a rescue proves exclusivity"],
    statements: [
      truth(`The data support this limited conclusion: ${experiment.conclusion}`, true, "This restates the narrow, supported conclusion."),
      truth(experiment.overreach, false, "This extends beyond the conditions and measurements in the case."),
      truth(`The pathway model predicts: ${experiment.prediction}`, true, "The prediction follows the stated direction of regulation."),
      truth(`The experiment rules out this alternative completely: ${experiment.alternative}`, false, "The alternative remains testable; one experiment rarely eliminates every confounder.")
    ]
  };
  caseItem.questions = makeQuestions(caseItem);
  return caseItem;
}));
